CREATE SCHEMA IF NOT EXISTS private; GRANT USAGE ON SCHEMA private TO authenticated; CREATE FUNCTION private.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$; GRANT EXECUTE ON FUNCTION private.has_role(uuid, public.app_role) TO authenticated; DROP POLICY products_admin_write ON public.products; CREATE POLICY products_admin_write ON public.products FOR ALL TO authenticated USING (private.has_role(auth.uid(), 'admin')) WITH CHECK (private.has_role(auth.uid(), 'admin')); DROP POLICY orders_admin_read ON public.orders; CREATE POLICY orders_admin_read ON public.orders FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin')); DROP POLICY orders_admin_update ON public.orders; CREATE POLICY orders_admin_update ON public.orders FOR UPDATE TO authenticated USING (private.has_role(auth.uid(), 'admin')) WITH CHECK (private.has_role(auth.uid(), 'admin')); DROP POLICY order_items_admin_read ON public.order_items; CREATE POLICY order_items_admin_read ON public.order_items FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin')); DROP FUNCTION public.has_role(uuid, public.app_role);